import sys

def find_valid_expressions(a, b, c, d):
    operators = ['+', '-', '*', '/']
    valid_expressions = []

    for op1 in operators:
        for op2 in operators:
            if op2 == '/' and (c == 0 or d == 0):
                continue
            expr1 = f"{a} {op1} {b}"
            expr2 = f"{c} {op2} {d}"
            result1 = eval(expr1)
            result2 = eval(expr2)
            if result1 == result2:
                valid_expressions.append(f"{expr1} = {expr2}")

    if not valid_expressions:
        print("problems ahead")
    else:
        for expr in sorted(valid_expressions):
            print(expr)

if __name__ == "__main__":
    input_line = input().strip()
    a, b, c, d = map(int, input_line.split())
    find_valid_expressions(a, b, c, d)
```

