def find_valid_expressions(a, b, c, d):
    operators = ['+', '-', '*', '/']
    valid_expressions = []

    for op1 in operators:
        for op2 in operators:
            try:
                if eval(f"{a} {op1} {b} == {c} {op2} {d}"):
                    expression = f"{a} {op1} {b} = {c} {op2} {d}"
