import sys

def min_final_health(N, A):
    while len(A) > 1:
        i = j = -1
        max_attack = -1
        for k in range(len(A)):
            if A[k] > 0:
                if i == -1 or A[k] >= max_attack:
                    max_attack = A[k]
                    i, j = (i, k) if i != -1 else (k, k)
                elif A[k] < max_attack:
                    continue
        A[i] -= A[j]
        A[j] = 0
    return A[0]

if __name__ == "__main__":
    N = int(input())
    A = list(map(int, input().split()))
    print(min_final_health(N, A))
