import sys

def min_watering_operations(N, h):
    operations = 0
    current_heights = [0] * N

    for i in range(N):
        if h[i] > current_heights[i]:
            operations += 1
            for j in range(max(0, i-1), min(N, i+2)):
                current_heights[j] += 1

    return operations

