def split_sequence(n, a):
    increasing = []
    decreasing = []
    i = 0
    while i < n:
        if not increasing or a[i] > increasing[-1]:
            increasing.append(a[i])
        else:
            break
        i += 1

    j = i
    while j < n:
        if not decreasing or a[j] < decreasing[-1]:
            decreasing.append(a[j])
        else:
            break
        j += 1

    if i == n and j == n:
        result = [0] * n
        for k in range(len(increasing)):
            result[a.index(increasing[k])] = 0
        for k in range(len(decreasing)):
