import sys
from collections import deque

def refill_fridge(n, m, s, d, current):
    if sum(current) < n:
        return "impossible"

    slots = [deque([0] * c for c in current)]
    new_bottles = deque(range(n))

    def can_refill(refill_scheme):
        for i, count in enumerate(refill_scheme):
            if count > d - current[i]:
                return False
        return True

    def simulate(refill_scheme):
        slots = [deque([0] * c for c in current)]
        new_bottles = deque(range(n))

        for count in refill_scheme:
            slots[0].extendleft(reversed(new_bottles[:count]))
            new_bottles = new_bottles[count:]

        cold_count = 0
        for _ in range(m):
            if not slots:
                return False
            slot = slots.popleft()
            if slot[-1] == 0:
                continue
            slot.pop()
            cold_count += 1

        return cold_count == m

    best_refill = None
    max_cold_probability = 0

    for i in range(n + 1):
        for j in range(n - i + 1):
            refill_scheme = [i, j, n - i - j]
            if can_refill(refill_scheme) and simulate(refill_scheme):
                cold_probability = (n - sum(refill_scheme)) / n
                if cold_probability > max_cold_probability:
                    max_cold_probability = cold_probability
                    best_refill = refill_scheme

    return best_refill

if __name__ == "__main__":
