def find_pairs(l, r):
    if (r - l) % 2 != 1:
        return "NO"

    pairs = []
    for i in range(l, r + 1):
        found_pair = False
        for j in range(i + 1, r + 1):
            if gcd(i, j) == 1:
                pairs.append((i, j))
                found_pair = True
                break
        if not found_pair:
            return "NO"

    return "YES\n" + "\n".join(f"{a} {b}" for a, b in pairs)

