def max_number(n):
    if n == 2:
        return 1
    elif n == 3:
        return 7
    else:
        digits = [1, 7, 4, 2, 5]
        result = []
        for digit in digits:
            while n >= sum(int(x) for x in str(digit)):
                result.append(str(digit))
                n -= sum(int(x) for x in str(digit))
        return int(''.join(result))

