import sys

def main():
    n = int(input())
    x = list(map(int, input().split()))

    min_val = min(x)
    max_val = max(x)
    avg = sum(x) / n

    y = []
    equal_count = 0

    for xi in x:
        if xi == avg:
            y.append(avg)
            equal_count += 1
        else:
            if xi < avg and xi + 1 <= max_val:
                y.append(xi + 1)
            elif xi > avg and xi - 1 >= min_val:
                y.append(xi - 1)
            else:
                y.append(xi)

    print(equal_count)
    print(' '.join(map(str, y)))

if __name__ == "__main__":
    main()
