import math

def count_elegant_numbers(n):
    def prime_factors(x):
        factors = []
        for i in range(2, int(math.sqrt(x)) + 1):
            while x % i == 0:
                factors.append(i)
                x //= i
        if x > 1:
            factors.append(x)
        return factors

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def gcd_list(lst):
        return reduce(gcd, lst)

    count = 0
    for i in range(2, n + 1):
        factors = prime_factors(i)
        if gcd_list(factors) == 1:
            count += 1
    return count

T = int(input())
