def count_ways_to_award_diplomas(n, scores):
    ways = 0
    for i in range(1 << n):
        awarded = [False] * n
        max_score = -1
        for j in range(n):
            if i & (1 << j):
                if scores[j] == 0:
                    break
                awarded[j] = True
                max_score = max(max_score, scores[j])
        else:
            for j in range(n):
                if scores[j] >= max_score and not awarded[j]:
                    break
            else:
                ways += 1
    return ways

