def palindromic_characteristics(s):
    n = len(s)
    dp = [[[0] * (n + 1) for _ in range(n)] for _ in range(n)]

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if length == 1:
                dp[i][j][1] = 1
            elif s[i] == s[j]:
                dp[i][j][1] = dp[i + 1][j - 1][1] + 2 * (length > 2) + 1
                for k in range(2, length + 1):
                    dp[i][j][k] = dp[i + 1][j - 1][k - 1]
            else:
                dp[i][j][1] = dp[i + 1][j][1] + dp[i][j - 1][1] - dp[i + 1][j - 1][1]
                for k in range(2, length + 1):
                    dp[i][j][k] = max(dp[i + 1][j][k], dp[i][j - 1][k])

    result = [0] * n
    for i in range(n):
        for j in range(i, n):
            for k in range(1, n + 1):
                if dp[i][j][k] > 0:
                    result[j - i] += dp[i][j][k]

    print(' '.join(map(str, result)))

