import sys
from collections import deque

def min_magic_moves(H, W, C_h, C_w, D_h, D_w, S):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and S[x][y] == '.'

    def bfs():
        queue = deque([(C_h, C_w, 0)])
        visited = set()
        visited.add((C_h, C_w))

        while queue:
            x, y, magic_used = queue.popleft()

            if (x, y) == (D_h, D_w):
                return magic_used

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, magic_used))

            if magic_used < 2:
                for i in range(max(0, x-2), min(H, x+3)):
                    for j in range(max(0, y-2), min(W, y+3)):
                        if is_valid(i, j) and (i, j) not in visited:
                            visited.add((i, j))
                            queue.append((i, j, magic_used + 1))

        return -1

    return bfs()

