def find_max_elevation_changes(n, m, terrain):
    max_climb = 0
    max_descent = 0
    current_height = 0

    for col in range(m):
        height = 0
        for row in range(n-1, -1, -1):
            if terrain[row][col] == '*':
                height += 1
            else:
                break
        if height > 0:
            if current_height < height:
                max_climb = max(max_climb, height - current_height)
            elif current_height > height:
                max_descent = max(max_descent, current_height - height)
            current_height = height

    return max_climb, max_descent

