    colors = list(range(1, N + 1))

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W

    def bfs(start_x, start_y, color):
        queue = deque([(start_x, start_y)])
        visited = set()
        visited.add((start_x, start_y))
        grid[start_x][start_y] = color

        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
