def min_nights_and_splits(n):
    if n == 1:
        return 0, []

    days = 0
    splits = []
    current_mass = 1

    while current_mass < n:
        days += 1
        split_count = 0
        for i in range(len(splits)):
            if splits[i] > 0:
                splits[i] -= 1
                split_count += 1
                current_mass += 1
        if current_mass >= n:
            break
        splits.append(2)

    return days, splits

