    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        days, splits = min_nights_and_splits(n)
        if days == -1:
            results.append(-1)
        else:
            results.append(days)
            results.extend(splits)

    for result in results:
        print(result)

if __name__ == "__main__":
