from itertools import permutations

def can_reorder_to_sum(a, m):
    n = len(a)
    for perm in permutations(a):
        total_sum = 0
        for i in range(n):
            inner_sum = sum(perm[j] / (j + 1) for j in range(i, n))
            total_sum += inner_sum
            if total_sum > m:
                break
        if total_sum == m:
            return True
    return False

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        m = int(data[index + 1])
        a = list(map(int, data[index + 2:index + 2 + n]))
        index += 2 + n

        if can_reorder_to_sum(a, m):
            results.append("YES")
        else:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
