def min_changes_to_rectangle(n, m, k, table):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m

    def dfs(x, y, value):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if not is_valid(cx, cy) or table[cx][cy] != value:
                continue
            table[cx][cy] = -1
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                stack.append((cx + dx, cy + dy))

    changes = 0
    for i in range(n):
        for j in range(m):
            if table[i][j] == 1:
                dfs(i, j, 1)
            elif table[i][j] == 0:
                dfs(i, j, 0)

    for i in range(n):
        for j in range(m):
            if table[i][j] != -1:
                changes += 1

    if changes > k:
        return -1
    else:
        return changes

