def count_sequences(a11, a12, a21, a22, N):
    if N == 0:
        return 1

    total_players = a11 + a12 + a21 + a22
    dp = [[[[0] * (total_players + 1) for _ in range(total_players + 1)] for _ in range(3)] for _ in range(3)]

    dp[1][1][0][0] = a11
    dp[1][2][0][0] = a12
    dp[2][1][0][0] = a21
    dp[2][2][0][0] = a22

    for _ in range(1, N):
        new_dp = [[[[0] * (total_players + 1) for _ in range(total_players + 1)] for _ in range(3)] for _ in range(3)]

        for i in range(1, total_players + 1):
            for j in range(1, total_players + 1):
                if dp[1][1][i-1][j] > 0:
                    new_dp[2][1][i][j] = (new_dp[2][1][i][j] + dp[1][1][i-1][j]) % MOD
                if dp[1][2][i-1][j] > 0:
                    new_dp[2][2][i][j] = (new_dp[2][2][i][j] + dp[1][2][i-1][j]) % MOD
                if dp[2][1][i-1][j] > 0:
                    new_dp[1][1][i][j] = (new_dp[1][1][i][j] + dp[2][1][i-1][j]) % MOD
                if dp[2][2][i-1][j] > 0:
                    new_dp[1][2][i][j] = (new_dp[1][2][i][j] + dp[2][2][i-1][j]) % MOD

        dp = new_dp

    result = sum(dp[i][j][total_players][total_players] for i in range(1, total_players + 1) for j in range(1, total_players + 1)) % MOD
    return result

