        if balance == 0:
            return True
        if k == 0:
            return False
        for i in range(n):
            if (balance > 0 and sequence[i] == '(') or (balance < 0 and sequence[i] == ')'):
                if costs[i] <= 0:
                    if can_balance(k - 1, balance + (-2 * sequence[i] + 1)):
                        return True
        return False

    min_effort = float('inf')
    for i in range(n):
        if costs[i] < 0:
            new_sequence = list(sequence)
            new_sequence[i] = '(' if sequence[i] == ')' else ')'
            if not can_balance(k - 1, sum(1 if x == '(' else -1 for x in new_sequence)):
                min_effort = min(min_effort, costs[i])
    return min_effort if min_effort != float('inf') else '?'

