import sys
from fractions import Fraction

def bfs(start, end, graph):
    queue = [(start, 0)]
    visited = set()
    while queue:
        node, time = queue.pop(0)
        if node == end:
            return time
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, time + 1))
    return float('inf')

def captain_safety(N, L, walk, graph):
    total_time = sum(walk[1:])
    sentry_positions = [0] * N
    sentry_positions[walk[0]] += 1

    for i in range(1, L):
        current_room = walk[i]
        next_room = walk[i - 1]
        time_to_next = bfs(current_room, next_room, graph)
        if time_to_next == float('inf'):
            return Fraction(0)

        sentry_positions[next_room] += sentry_positions[current_room] * (time_to_next / total_time)

    return Fraction(sentry_positions[walk[-1]])

if __name__ == "__main__":
    N = int(input())
    L = int(input())
    walk = list(map(int, input().split()))
    graph = [[] for _ in range(N)]
    for i in range(N):
        n_i = int(input())
        neighbors = list(map(int, input().split()))
        graph[i] = neighbors

    result = captain_safety(N, L, walk, graph)
    print(result)
