def is_valid_divisibility_hack(b, d):
    if b == d:
        return "no"
    for m in range(1, 20):  # Check for a reasonable range of m values
        valid = True
        for n in range(d):
            if (n ** b) % d != f_b_m(n, b, m) % d:
                valid = False
                break
        if valid:
            return "yes"
    return "no"

def f_b_m(n, b, m):
    digits = []
    while n > 0:
        digits.append(n % b)
        n //= b
    k = len(digits)
    result = 0
    sign = 1
    for i in range(k):
        if (i // m) % 2 == 0:
            result += sign * sum(digits[i:i+m])
        else:
            result -= sign * sum(digits[i:i+m])
        sign *= -1
    return result

