def digit_product_distribution(L, R):
    def product_of_digits(n):
        product = 1
        while n > 0:
            digit = n % 10
            if digit != 0:
                product *= digit
            n //= 10
        return product

    count = [0] * 9
    for x in range(L, R + 1):
        result = product_of_digits(x)
        if 1 <= result <= 9:
            count[result - 1] += 1
    print(' '.join(map(str, count)))

