def simulate_planetoid_collisions():
    import sys
    input = sys.stdin.read
    data = input().split()

    n, nx, ny, nz = int(data[0]), int(data[1]), int(data[2]), int(data[3])
    planetoids = []

    index = 4
    for _ in range(n):
        m = int(data[index])
        x, y, z = int(data[index + 1]), int(data[index + 2]), int(data[index + 3])
        vx, vy, vz = int(data[index + 4]), int(data[index + 5]), int(data[index + 6])
        planetoids.append((m, (x, y, z), (vx, vy, vz)))
        index += 7

    def get_next_position(pos, vel):
        return ((pos[0] + vel[0]) % nx, (pos[1] + vel[1]) % ny, (pos[2] + vel[2]) % nz)

    while True:
        collisions = {}
        for i in range(n):
            pos1, vel1 = planetoids[i][1], planetoids[i][2]
            next_pos1 = get_next_position(pos1, vel1)
            if next_pos1 not in collisions:
                collisions[next_pos1] = []
            collisions[next_pos1].append((i, planetoids[i]))

        new_planetoids = []
        for pos, entries in collisions.items():
            if len(entries) > 1:
                total_mass = sum(m for m, _, _ in entries)
                avg_vel = (sum(vx for m, (_, _, (vx, vy, vz)), _ in entries) // len(entries),
                           sum(vy for m, (_, _, (vx, vy, vz)), _ in entries) // len(entries),
                           sum(vz for m, (_, _, (vx, vy, vz)), _ in entries) // len(entries))
                new_planetoids.append((total_mass, pos, avg_vel))
            else:
                new_planetoids.extend(entries)

        if len(new_planetoids) == n:
            break
        planetoids = new_planetoids
        n = len(planetoids)

    planetoids.sort(key=lambda x: (-x[0], x[1]))

    print(len(planetoids))
    for i, (m, pos, vel) in enumerate(planetoids):
        print(f"P{i}: {m} {pos[0]} {pos[1]} {pos[2]} {vel[0]} {vel[1]} {vel[2]}")
