def find_permutation(N, A, B):
    if N == 1:
        return [1] if A == 1 else -1

    if A > B or A < 1 or B < 1:
        return -1

    permutation = list(range(1, N + 1))

    for i in range(N):
        if (i + 1) % A == 0:
