import sys
from collections import defaultdict

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def lowest_prime_divisor(n):
    for factor in prime_factors(n):
        return factor

def find_min_path_sum(n, k_values):
    graph = defaultdict(list)
    visited = set()

    def dfs(node):
        if node in visited:
            return 0
        visited.add(node)
        min_distance = float('inf')
        for neighbor in graph[node]:
            min_distance = min(min_distance, dfs(neighbor))
        return 1 + min_distance

    for k in k_values:
