import sys
from collections import defaultdict

def count_ways_to_place_guards(N, trenches):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def line_equation(p1, p2):
        (x1, y1), (x2, y2) = p1, p2
        dx, dy = x2 - x1, y2 - y1
        g = gcd(dx, dy)
        return (dx // g, dy // g, x1 * dy - y1 * dx)

    lines = defaultdict(list)
    for i in range(N):
        for j in range(i + 1, N):
            line = line_equation((trenches[i][0], trenches[i][1]), (trenches[j][0], trenches[j][1]))
            lines[line].append((i, j))

    ways = 0
    for line, pairs in lines.items():
        if len(pairs) >= 3:
            ways += len(pairs) * (len(pairs) - 1) // 2

    return ways

if __name__ == "__main__":
    N = int(input())
    trenches = [tuple(map(int, input().split())) for _ in range(N)]
    print(count_ways_to_place_guards(N, trenches))
