    n = len(stickers)
    sticker_dict = defaultdict(list)

    for word, price in stickers:
        sticker_dict[word].append(price)

    dp = [[float('inf')] * (len(message) + 1) for _ in range(len(message) + 1)]
    dp[0][0] = 0

    for i in range(1, len(message) + 1):
        for j in range(i - 1, -1, -1):
            word = message[j:i]
            if word in sticker_dict:
                for price in sticker_dict[word]:
                    dp[i][j] = min(dp[i][j], dp[j][j] + price)

    if dp[len(message)][0] == float('inf'):
        return "IMPOSSIBLE"
    else:
        return dp[len(message)][0]

