import sys
from collections import defaultdict, deque

def find_division(n, c, encounters):
    graph = defaultdict(list)
    for a, b, y in encounters:
        graph[a].append((b, y))
        graph[b].append((a, y))

    def bfs(start):
        queue = deque([start])
        visited = set()
        year = float('inf')
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor, y in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
                        year = min(year, y)
        return year

    max_year = 0
    for i in range(1, n + 1):
        max_year = max(max_year, bfs(i))

    if max_year == float('inf'):
        return 'Impossible'

    def can_divide(Y):
        first_part = set()
        second_part = set()
        queue = deque([1])
        visited = {1}
        while queue:
            node = queue.popleft()
            if node in first_part and node in second_part:
                return False
            for neighbor, y in graph[node]:
                if y < Y and neighbor not in visited:
                    first_part.add(neighbor)
                    visited.add(neighbor)
                    queue.append(neighbor)
                elif y >= Y and neighbor not in visited:
                    second_part.add(neighbor)
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(first_part) <= 2 * n // 3 and len(second_part) <= 2 * n // 3

    left, right = max_year, 2007
    while left < right:
        mid = (left + right) // 2
        if can_divide(mid):
            right = mid
        else:
            left = mid + 1

    return str(left)

