    for _ in range(t):
        n = int(input())
        s = input().strip()
        returnable_count = 0

        for i in range(n):
            if s[i] == '-':
                continue

            visited = [False] * n
            stack = [(i, True), (i, False)]

            while stack:
                current, direction = stack.pop()
                if visited[current]:
                    break
                visited[current] = True

                next_room = (current + 1) % n
                prev_room = (current - 1) % n

                if s[next_room] == '>' and direction:
                    stack.append((next_room, True))
                elif s[next_room] == '<' and not direction:
                    stack.append((next_room, False))

                if s[prev_room] == '<' and direction:
                    stack.append((prev_room, False))
                elif s[prev_room] == '>' and not direction:
                    stack.append((prev_room, True))

            if all(visited):
                returnable_count += 1

    for result in results:
        print(result)

