import sys

def min_steps_to_friendship(n, m, friendships):
    graph = [[] for _ in range(n)]
    for u, v in friendships:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    def dfs(node, visited):
        stack = [node]
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return sum(visited) == n

    def find_min_steps():
        min_steps = float('inf')
        best_nodes = []
        for i in range(n):
            visited = [False] * n
            dfs(i, visited)
            if all(graph[i][j] or graph[j][i] for j in range(n)):
                continue
            steps = 0
            selected_nodes = []
            while not dfs(i, visited):
                for j in range(n):
                    if not visited[j]:
                        selected_nodes.append(j+1)
                        for k in range(n):
                            if not visited[k] and (j+1, k+1) not in friendships and (k+1, j+1) not in friendships:
                                graph[j][k] = True
                                graph[k][j] = True
                                visited[k] = True
                        steps += 1
            if steps < min_steps:
                min_steps = steps
                best_nodes = selected_nodes
        return min_steps, best_nodes

    min_steps, best_nodes = find_min_steps()
    print(min_steps)
    print(' '.join(map(str, best_nodes)))

