def min_turns_to_distinguish(n, A, B, intersections):
    def can_see_tower(start):
        stack = [start]
        while stack:
            current = stack.pop()
            if intersections[current][2] == 1:
                return True
            left, right = intersections[current][:2]
            if left != -1:
                stack.append(left)
            if right != -1:
                stack.append(right)
        return False

    if can_see_tower(A) and not can_see_tower(B):
        return 0
    elif not can_see_tower(A) and can_see_tower(B):
        return 0
    else:
        return "indistinguishable"

