def max_zebra_length(s):
    n = len(s)
    dp = [[0, 0] for _ in range(n)]
    if s[0] == 'b':
        dp[0][0] = 1
    else:
        dp[0][1] = 1

    for i in range(1, n):
        if s[i] == 'b':
            dp[i][0] = dp[i-1][1] + 1
            dp[i][1] = max(dp[i-1][0], dp[i-1][1])
        else:
            dp[i][1] = dp[i-1][0] + 1
            dp[i][0] = max(dp[i-1][0], dp[i-1][1])

    return max(max(dp[i]) for i in range(n))

