        queue = deque([start])
        visited[start] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return all(visited[i] for i in range(1, w + 1))

    for i in range(1, w + 1):
        if not visited[i]:
            if not bfs(i):
                return "impossible"

