from collections import Counter
import sys

MOD = 10**9 + 7

def count_valid_evolution_plans(n, m, gyms):
    total_pokemons = sum(g for g in gyms)
    type_counts = [Counter() for _ in range(m)]

    for i, gym in enumerate(gyms):
        for p in gym:
            type_counts[p-1][i] += 1

    def factorial(n):
        if n == 0 or n == 1:
            return 1
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % MOD
        return result

    def inverse_factorial(n):
        return pow(factorial(n), MOD - 2, MOD)

    valid_plans = factorial(m)
    for count in type_counts:
        valid_plans *= inverse_factorial(sum(count.values()))
        valid_plans %= MOD

    return valid_plans

if __name__ == "__main__":
    n, m = map(int, input().split())
    gyms = [list(map(int, input().split()))[1:] for _ in range(n)]
    result = count_valid_evolution_plans(n, m, gyms)
    print(result)
