        for p in gym:
            type_counts[p-1][i] += 1

    def factorial(n):
        if n == 0 or n == 1:
            return 1
        result = 1
        for i in range(2, n + 1):
            result = (result * i) % MOD
        return result

    def inverse_factorial(n):
        return pow(factorial(n), MOD - 2, MOD)

