import math
from scipy.special import erf, gamma, jn

def taylor_polynomial(a, b, c, t1, t2, t3, t4, r):
    def f(x):
        return c * (t1 * gamma(x) + (math.log(erf(t3 * x)) ** (1 / t2))) - (jn(t4, x) ** t4)

    def nth_derivative(f, n, x):
        if n == 0:
            return f(x)
        else:
            return nth_derivative(lambda x: (f(x + h) - f(x)) / h, n - 1, x)

    P = sum(nth_derivative(f, i, 0) / math.factorial(i) * x**i for i in range(r + 1))
    return P

def modified_polynomial(P, r, n):
    P_n = sum(P[i] * n**i for i in range(len(P)))
    return P_n

def final_polynomial(g, s, l):
    g_diff = g
    for _ in range(s + 1):
        g_diff = g_diff.diff()
    return (g_diff.subs('n', s) + l)**2 / math.pi * math.e + 1 / (l + 1)

def main():
    a, b, c = map(float, input().split())
    t1, t2, t3, t4 = map(int, input().split())
    n, k, r, s, l = map(int, input().split())

    P = taylor_polynomial(a, b, c, t1, t2, t3, t4, r)
    P_n = modified_polynomial(P, r, n)
    g = sympy.Function('g')(n)
    g_diff = final_polynomial(g, s, l)

    print(f"{g_diff.evalf():.6f}")

